import fs from "node:fs/promises";
import path from "node:path";

const root = path.resolve("..");
const outRoot = process.cwd();
const favoritesFile = path.join(outRoot, "favorites.json");
const assetsOut = path.join(outRoot, "assets");

function slugify(value) {
  return value
    .toLowerCase()
    .replace(/^downloaded\s*-\s*/i, "")
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/^-+|-+$/g, "")
    .slice(0, 90) || "asset";
}

async function exists(target) {
  try {
    await fs.access(target);
    return true;
  } catch {
    return false;
  }
}

async function main() {
  if (!(await exists(favoritesFile))) {
    throw new Error(`Missing ${favoritesFile}. Export favorites.json from the asset page first.`);
  }

  const payload = JSON.parse(await fs.readFile(favoritesFile, "utf8"));
  const favorites = Array.isArray(payload.assets) ? payload.assets : [];
  await fs.mkdir(assetsOut, { recursive: true });

  const copied = [];
  for (const asset of favorites) {
    if (!asset.localPath || !asset.localPath.startsWith("07-downloaded-2d-assets/extracted/")) continue;
    const source = path.join(root, asset.localPath);
    if (!(await exists(source))) continue;
    const folderName = slugify(asset.name);
    const target = path.join(assetsOut, folderName);
    await fs.rm(target, { recursive: true, force: true });
    await fs.cp(source, target, { recursive: true });
    copied.push({ ...asset, copiedPath: `assets/${folderName}/` });
  }

  await fs.writeFile(path.join(outRoot, "manifest.json"), `${JSON.stringify({ copiedAt: new Date().toISOString(), count: copied.length, assets: copied }, null, 2)}\n`);
  await fs.writeFile(path.join(outRoot, "index.html"), renderIndex(copied));
  console.log(`Copied ${copied.length} favorite asset folders into ${assetsOut}`);
}

function renderIndex(assets) {
  const cards = assets.map(asset => `
    <article class="card">
      <div class="thumb">${asset.thumbnailUrl ? `<img src="../${asset.thumbnailUrl}" alt="">` : ""}</div>
      <h2>${escapeHtml(asset.name)}</h2>
      <p>${escapeHtml(asset.bestFor || "")}</p>
      <p><strong>Local copy:</strong> <code>${escapeHtml(asset.copiedPath)}</code></p>
      <p><a href="${escapeHtml(asset.copiedPath)}">Open copied folder</a> · <a href="${escapeHtml(asset.downloadPage)}">Source</a></p>
    </article>
  `).join("");
  return `<!doctype html>
<html lang="zh-CN">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width, initial-scale=1">
  <title>收藏素材目录</title>
  <style>
    body{margin:0;background:#f5f7fa;color:#171b22;font-family:Inter,system-ui,-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif}
    .shell{width:min(1180px,calc(100% - 32px));margin:0 auto;padding:28px 0 48px}
    h1{margin:0 0 8px;font-size:34px}.intro{margin:0 0 22px;color:#687385}
    .grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(260px,1fr));gap:14px}
    .card{background:#fff;border:1px solid #d8dee7;border-radius:10px;padding:14px;box-shadow:0 10px 26px rgba(22,31,44,.08)}
    .thumb{height:128px;display:grid;place-items:center;background:#eef3f4;border:1px solid #d8dee7;border-radius:8px;overflow:hidden}
    .thumb img{max-width:100%;max-height:100%;object-fit:contain}
    h2{font-size:17px;line-height:1.2}p{color:#687385;font-size:13px}code{overflow-wrap:anywhere}
    a{color:#0b5752}
  </style>
</head>
<body><main class="shell"><h1>收藏素材目录</h1><p class="intro">已复制 ${assets.length} 个收藏素材包到本地 assets 文件夹。</p><section class="grid">${cards}</section></main></body>
</html>`;
}

function escapeHtml(value) {
  return String(value).replace(/[&<>"']/g, char => ({
    "&": "&amp;",
    "<": "&lt;",
    ">": "&gt;",
    '"': "&quot;",
    "'": "&#39;"
  })[char]);
}

main().catch(error => {
  console.error(error.message);
  process.exitCode = 1;
});

